{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret siger, at man skal vedlægge både epikrise/afslutningsnotat og journal fra egen læge for de seneste 2-3 år. Det gør journal fra egen læge til et kumulativt krav, og det er en væsentlig fejl efter rubrikken. Kravet om, at journalerne kan komme fra egen læge, speciallæge, hospital eller ambulant klinik, fremgår ikke. '2-3 år' har ingen støtte i de frosne kilder."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret nævner kun journal fra egen læge og epikrise fra hospital, klinik eller speciallæge. Det angiver ikke journalmateriale fra de fire behandlertyper som alternativer. Det kræver heller ikke, at materialet beskriver den varige funktionsnedsættelse; ordet 'varig' mangler. Kun elementet om epikrise som udgangspunkt er dækket."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken lægelig dokumentation der skal vedlægges, når behandlingen er afsluttet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret nævner identificerbare kilder: SU's dokumentationsside/vejledning, fodnotehenvisninger og SU-loven (LBK 395/2023) § 54 og § 46 h. Kernepåstandene er dog også mærket '(uden kilde)', så sporbarheden er svag."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "De viste lovparagraffer (SU-loven § 54 og § 46 h) er ikke de relevante bestemmelser. De frosne kilder peger på SU-bekendtgørelsen § 37, stk. 1, 3 og 4, samt vejledningens afsnit 4.1. Kilderne er derfor ikke anvendelige til opgaven."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De angivne paragraffer understøtter ikke påstandene om epikrise, egen læges journal og 2-3 år. De fleste kernepåstande er mærket '(uden kilde)'. Fodnoterne 1 og 2 kan ikke kobles til bestemte passager."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en periode på 2-3 år og en liste over, hvad dokumentationen bør vise: diagnose, hverdagspåvirkning, behandling og erhvervsevne. Det tilføjer også 'eventuelt yderligere nyere lægefaglig dokumentation'. Intet af det har støtte i de frosne kilder."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "'Som udgangspunkt' er bevaret for epikrisen. Svaret nævner ikke, at dokumentets titel ikke i sig selv afgør, om dokumentationen er tilstrækkelig. Journalkravet fra egen læge gengives uden alternativer. Afvisningen er blødgjort til 'kan risikere at blive afvist', mens vejledningen siger, at Udbetaling Danmark afviser."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "De synlige trin er indbyrdes sammenhængende: der kræves dokumentation, afsluttet behandling kræver epikrise, og manglende dokumentation kan give afvisning. Konklusionen følger af disse trin, selvom indholdet er delvist forkert."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'skal' om både epikrise og journal fra egen læge og gør dermed journalen til et absolut, kumulativt krav. 'Bør' og 'typisk' bruges om indholdet, selvom kilden siger 'skal' om minimumsdokumentationen. Modaliteten er derfor upræcis."
    }
  },
  "xhaile_coverage": {
    "A30": {
      "label": "yes",
      "reason": "Svaret angiver, at man som udgangspunkt skal vedlægge epikrise/afslutningsnotat, når behandlingen er afsluttet."
    },
    "A32": {
      "label": "yes",
      "reason": "Svaret siger, at dokumentationen ved afsluttet behandling som udgangspunkt omfatter en epikrise eller et afslutningsnotat. Det er dog formuleret som et krav ved siden af journal fra egen læge."
    }
  },
  "overall_notes": "Svaret rammer elementet om epikrise som udgangspunkt, men gør journal fra egen læge og en periode på 2-3 år til krav. Det mangler journalmateriale fra de fire behandlertyper som alternativer og kravet om beskrivelse af den varige funktionsnedsættelse. De viste kilder (SU-loven § 54 og § 46 h) er irrelevante, og kernepåstandene er mærket '(uden kilde)'."
}

